package au.edu.uow.csci318.planning.domain;import jakarta.persistence.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;
@Entity @Table(name="study_plans")public class StudyPlan{@Id private UUID id;@Column(nullable=false)private LocalDate startDate;@Column(nullable=false)private LocalDate endDate;@Column(nullable=false)private int version;@Lob @Column(nullable=false)private String itemsJson;@Column(nullable=false)private String explanation;@Column(nullable=false)private Instant createdAt;protected StudyPlan(){}public StudyPlan(LocalDate start,LocalDate end,int version,String json,String explanation){if(start==null||end==null||end.isBefore(start)||ChronoUnit.DAYS.between(start,end)!=6)throw new IllegalArgumentException("Planning period must contain exactly seven days");id=UUID.randomUUID();startDate=start;endDate=end;this.version=version;itemsJson=Objects.requireNonNull(json);this.explanation=explanation==null?"":explanation;createdAt=Instant.now();}public UUID getId(){return id;}public LocalDate getStartDate(){return startDate;}public LocalDate getEndDate(){return endDate;}public int getVersion(){return version;}public String getItemsJson(){return itemsJson;}public String getExplanation(){return explanation;}public Instant getCreatedAt(){return createdAt;}}
